import org.jsoup.nodes.TextNode;
import org.jsoup.nodes.Document;
import org.junit.Test;
import org.junit.Assert;

public class TextNodeTest {
    @Test
    public void textNodeConstructorTest() {
        TextNode textNode = new TextNode("sample text");
        Assert.assertNotNull(textNode);
    }

    @Test
    public void nodeNameTest() {
        TextNode textNode = new TextNode("sample text");
        Assert.assertEquals("#text", textNode.nodeName());
    }

    @Test
    public void textTest() {
        TextNode textNode = new TextNode("sample text");
        Assert.assertEquals("sample text", textNode.text());
    }

    @Test
    public void textSetTest() {
        TextNode textNode = new TextNode("sample text");
        textNode.text("new text");
        Assert.assertEquals("new text", textNode.text());
    }

    @Test
    public void getWholeTextTest() {
        TextNode textNode = new TextNode("sample text");
        Assert.assertEquals("sample text", textNode.getWholeText());
    }

    @Test
    public void isBlankTest() {
        TextNode textNode = new TextNode("");
        Assert.assertTrue(textNode.isBlank());
    }

    @Test
    public void splitTextTest() {
        TextNode textNode = new TextNode("sample text");
        TextNode split = textNode.splitText(6); 
        Assert.assertEquals("sample", textNode.getWholeText());
        Assert.assertEquals(" text", split.getWholeText());
    }

    @Test
	public void createFromEncodedTest() {
		TextNode textNode = TextNode.createFromEncoded("sample text");
		Assert.assertNotNull(textNode);
	}

	@Test
	public void normaliseWhitespaceTest() {
		String output = TextNode.normaliseWhitespace(" sample   text  ");
		Assert.assertEquals(" sample text ", output);
	}

	@Test
	public void stripLeadingWhitespaceTest() {
		String output = TextNode.stripLeadingWhitespace("  sample text");
		Assert.assertEquals("sample text", output);
	}

	@Test
	public void lastCharIsWhitespaceTest() {
		boolean lastIsWhitespace = TextNode.lastCharIsWhitespace(new StringBuilder("sample text "));
		Assert.assertTrue(lastIsWhitespace);
	}

	@Test
	public void toStringTest() {
		TextNode textNode = new TextNode("sample text");
		String output = textNode.toString();
		Assert.assertTrue(output.startsWith("TextNode"));
		Assert.assertTrue(output.contains("sample text"));
	}

	@Test
	public void cloneTest() {
		TextNode textNode = new TextNode("sample text");
		TextNode cloned = textNode.clone();
		Assert.assertEquals(textNode.text(), cloned.text());
		Assert.assertNotSame(textNode, cloned);
	}
}
